def build(a):
    n = a["cols"] * a["rows"]
    body = a["body"].replace("{soft}", SOFT).replace("{arcs}", ARCS_ALWAYS.format(extra=a["arcs_extra"]).strip())
    head = "DARK SLIME: %s. Written 2026-11-09. %s\n\n%s\n\n%s\n\n" % (a["title"], a["intro"], a["what"], LESSONS)
    how = """HOW TO USE
- Attach ONE image: Animations/DarkSlime/reference_image.png (the accepted dark look: deep-violet matte body with black spirals, a crown of horns, violet crescents and ink blobs, thin near-black indigo outline, flat green background). Ask for a %s image, as large as it will give you. Paste everything between the two lines of equals signs. Gemini (its JPG is fine; do not re-save it in an editor).
- Generate several and keep the best. Save it in inbox/ (for example inbox/Gemini_slime_dark_%s_sheet.jpg) and tell me. I cut it, measure it and put it in the page.
- OPTIONAL second try if the poses are wrong: also attach the ice slime's matching sheet (Animations/IceSlime/%s/source/%s) and put this sentence first: 'The second image is only the LAYOUT and the POSES to copy: the same panels in the same order, the same body motion and timing, the same floor. Draw the DARK slime of the first image in them, not the ice slime, on a flat GREEN background; its horns stay solid and its crescents and ink blobs replace the snowflakes and ice chips.'
- What I check: %s
- Planned cut: %s
""" % (a["ratio"], a["tag"], a["ice"], a["ice_sheet"], a["check"], a["cut"])
    rep = REPLIES.format(specific=a["specific"]) + "\n\n"
    grid = "%d columns x %d rows, %s equal panels" % (a["cols"], a["rows"], {6: "six", 8: "eight"}[n])
    prompt = """==============================================================================
OUTPUT: exactly ONE static image, a sprite sheet, and nothing else. Do NOT create a GIF, an animation, a video, a preview, extra images, alternate versions or a second attempt. No other files.

Create the sprite sheet: a grid of %s, read left to right, top row first, then the bottom row. %s

%s

%s

%s

""" % (grid, a["what"].split("WHAT IT IS. ", 1)[1].split(". ")[0] + ".", CHARACTER, VIEW, body)
    prompt += BACKGROUND + "\n\nFINAL REMINDER: output ONE single static image only. No GIF, no extra images. " + a["final"] + "\n==============================================================================\n"
    return head + how + rep + prompt


for a in ANIMS:
    d = os.path.join(ROOT, "Animations", "DarkSlime", a["folder"], "source")
    os.makedirs(d, exist_ok=True)
    path = os.path.join(d, a["folder"] + "_gemini_prompt.txt")
    open(path, "w", encoding="utf-8").write(build(a))
    print("wrote", os.path.relpath(path, ROOT), os.path.getsize(path), "bytes")
